// València's real buildings in the detailed city, generated by tools/realism/build-buildings.py: Catastro INSPIRE
// footprints (© Dirección General del Catastro) at PNOA-LiDAR heights and roof shapes (LiDAR-PNOA-cob3 2022-2025
// CC-BY 4.0 scne.es).
//
// VLB3 (gzipped; VLB2 has no roof colours): header [magic, buildings, boxes, roof houses, 10 section byte lengths], then
//   frames  f32 [px, pz, th] per building: its frame (local +x along the footprint's long axis, buildings.js xf)
//   meta    u8  [facade material, tone, construction decade - 150 (0 unknown), flags (1: storefronts)]
//   counts  u16 boxes per building
//   boxes   i16 [x0, x1, z0, z1, height] per box, decimetres, x/z relative to (px, pz) in the building's frame
//   faces   u8  WALL_KINDS of the box's w, e, n, s walls, 2 bits each
//   roof    u8  per box: 0 flat terrace (height includes a parapet), 1 gable with its ridge along x, 2 along z
//   rise    u8  per box: the gable's ridge above the eaves, decimetres
//   hcounts u8  roof (stair / lift) houses per building
//   houses  i16 [x0, x1, z0, z1, y0, height] per roof house, decimetres, relative to (px, pz) in the frame
//   roofRGB u8  [r, g, b] per box: its roof's colour on the PNOA orthophoto (PNOA cedido por © IGN, CC BY 4.0)
const response = await fetch(new URL('./vlc-buildings.bin.gz', import.meta.url));
if (!response.ok) throw new Error(`Building data request failed: ${response.status}`);
// Servers that send .gz files as Content-Encoding: gzip hand over bytes the browser has already inflated
const body = new Uint8Array(await response.arrayBuffer());
const data = body[0] === 0x1f && body[1] === 0x8b
  ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
  : body;
const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
const magic = String.fromCharCode(...data.subarray(0, 4));
if (data.length < 52 || (magic !== 'VLB2' && magic !== 'VLB3')) throw new Error('Invalid building data.');
const nSections = magic === 'VLB3' ? 10 : 9;
const count = view.getUint32(4, true);
const boxCount = view.getUint32(8, true);
const houseCount = view.getUint32(12, true);
const lens = Array.from({ length: nSections }, (_, k) => view.getUint32(16 + k * 4, true));
let at = 16 + nSections * 4;
const section = (Type, len) => {
  const out = new Type(data.slice(at, at + len).buffer);
  at += len;
  return out;
};
const frames = section(Float32Array, lens[0]);
const meta = section(Uint8Array, lens[1]);
const counts = section(Uint16Array, lens[2]).subarray(0, count);
const boxes = section(Int16Array, lens[3]).subarray(0, boxCount * 5);
const faces = section(Uint8Array, lens[4]).subarray(0, boxCount);
const roof = section(Uint8Array, lens[5]).subarray(0, boxCount);
const rise = section(Uint8Array, lens[6]).subarray(0, boxCount);
const houseCounts = section(Uint8Array, lens[7]).subarray(0, count);
const houses = section(Int16Array, lens[8]).subarray(0, houseCount * 6);
// VLB3: each box's roof colour from the PNOA orthophoto (sRGB, 0 0 0 unknown; tools/realism/roof-colors.py)
const roofRGB = nSections > 9 ? section(Uint8Array, lens[9]).subarray(0, boxCount * 3) : null;

export const REAL_BUILDINGS = { count, boxCount, houseCount, frames, meta, counts, boxes, faces, roof, rise, houseCounts, houses, roofRGB };
